import{_ as a,c as t,o as e,ag as l}from"./chunks/framework.ymCRTBvy.js";const m=JSON.parse('{"title":"📘 《iOS动画与手势实战：纯代码UIKit精解》","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/animation/index.md","filePath":"uikit/animation/index.md"}'),n={name:"uikit/animation/index.md"};function o(r,i,s,d,_,c){return e(),t("div",null,i[0]||(i[0]=[l('<h1 id="📘-《ios动画与手势实战-纯代码uikit精解》" tabindex="-1">📘 《iOS动画与手势实战：纯代码UIKit精解》 <a class="header-anchor" href="#📘-《ios动画与手势实战-纯代码uikit精解》" aria-label="Permalink to &quot;📘 《iOS动画与手势实战：纯代码UIKit精解》&quot;">​</a></h1><h2 id="📖-内容简介" tabindex="-1">📖 内容简介： <a class="header-anchor" href="#📖-内容简介" aria-label="Permalink to &quot;📖 内容简介：&quot;">​</a></h2><p>本书是面向中高级iOS开发者的实战技术指南，专注于UIKit框架下的动画编程与手势交互的深度实践。全书从动画核心概念与图层系统入手，系统讲解UIView动画、Core Animation高级特性、手势识别机制，并深入探讨物理引擎与自定义转场动画的实现。</p><p>不同于基础教程，本书特别关注复杂动画效果在实际项目中的工程化应用，提供大量性能优化方案和交互设计思路。涵盖从基础属性动画到关键帧动画，从简单手势处理到复杂手势冲突解决，帮助开发者掌握iOS动画与交互开发的完整技术栈。</p><p>通过19个精心设计的章节，本书系统性地讲解了如何构建流畅、自然且富有表现力的动画交互体验，每章都配有可直接应用于生产环境的代码示例和最佳实践。</p><h2 id="✅-你将学到" tabindex="-1">✅ 你将学到： <a class="header-anchor" href="#✅-你将学到" aria-label="Permalink to &quot;✅ 你将学到：&quot;">​</a></h2><ul><li>熟练掌握UIKit视图与图层动画编程</li><li>精通Core Animation框架实现复杂动画</li><li>能够纯代码构建无故事板的iOS界面</li><li>深入理解并应用各种手势识别器</li><li>实现自定义视图控制器转场动画</li><li>掌握UIKit Dynamics物理引擎效果</li><li>创建响应式和交互式动画体验</li><li>处理动画中断与状态更新</li><li>实现多步、链式及路径动画</li><li>解决手势冲突并实现手势共存</li></ul><p>本书适合已掌握UIKit基础知识，希望深入理解动画原理并解决复杂交互开发挑战的中高级开发者。通过学习本书，您将能够构建出动画流畅、交互自然且完全基于代码的iOS应用，掌握高级动画编程技巧，为用户提供卓越的动态交互体验。</p>',8)]))}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
